        match = url3.match(/queue\.amazonaws\.com\/(\d+)\/(.+)/);
        if (match) {
          const [, accountId, queueName] = match;
          const region = process.env.AWS_REGION || "us-east-1";
          return `arn:aws:sqs:${region}:${accountId}:${queueName}`;
        }
        return url3;
