    const spend = Number(t7.spend) || 0;
    const sales = Number(t7.sales) || 0;
    const orders = Number(t7.orders) || 0;
    const ctr = impressions > 0 ? clicks / impressions * 100 : 0;
    const cvr = clicks > 0 ? orders / clicks * 100 : 0;
