    criticalIssues.push(`${bidEfficiency.overbiddingCount}\u4E2A\u6295\u653E\u8BCD\u5B58\u5728\u8FC7\u5EA6\u7ADE\u4EF7\u95EE\u9898`);
    potentialSavings += bidEfficiency.totalPotentialSavings;
