          hot: { total: 0, completed: 0, failed: 0, pending: 0, processing: 0, percent: 0 },
          warm: { total: 0, completed: 0, failed: 0, pending: 0, processing: 0, percent: 0 },
          cold: { total: 0, completed: 0, failed: 0, pending: 0, processing: 0, percent: 0 }
